import{B as e,Q as t,s as n,z as r}from"./chunks/framework.3ZETo7pw.js";var i=JSON.parse(`{"title":"Database & Models","description":"","frontmatter":{},"headers":[],"relativePath":"backend/database.md","filePath":"backend/database.md"}`),a={name:`backend/database.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e('<h1 id="database-models" tabindex="-1">Database &amp; Models <a class="header-anchor" href="#database-models" aria-label="Permalink to &quot;Database &amp; Models&quot;">​</a></h1><p>TechyNews uses MySQL 8.0+ as its primary data store. The database schema is designed to support the extensive content generation capabilities of the platform, with a focus on speed and multi-lingual support.</p><h2 id="core-models" tabindex="-1">Core Models <a class="header-anchor" href="#core-models" aria-label="Permalink to &quot;Core Models&quot;">​</a></h2><h3 id="article" tabindex="-1"><code>Article</code> <a class="header-anchor" href="#article" aria-label="Permalink to &quot;`Article`&quot;">​</a></h3><p>The <code>Article</code> model is the central entity. It represents a single news story, whether it&#39;s a draft generated by AI or a published piece.</p><p><strong>Key Columns:</strong></p><ul><li><code>title</code> (string): The headline of the article.</li><li><code>slug</code> (string): SEO-friendly URL identifier.</li><li><code>summary</code> (text): A short excerpt or summary generated by the AI.</li><li><code>content</code> (longtext): The full body of the article stored as <strong>raw HTML</strong>. Storing raw HTML maximizes rendering speed by eliminating the need for complex parsing on the frontend.</li><li><code>translations</code> (json): A JSON column used to store localized versions of the title, summary, and content.</li></ul><h3 id="category-tag" tabindex="-1"><code>Category</code> &amp; <code>Tag</code> <a class="header-anchor" href="#category-tag" aria-label="Permalink to &quot;`Category` &amp; `Tag`&quot;">​</a></h3><p>Articles can be categorized and tagged to improve discoverability.</p><h2 id="important-rules-for-content-storage" tabindex="-1">Important Rules for Content Storage <a class="header-anchor" href="#important-rules-for-content-storage" aria-label="Permalink to &quot;Important Rules for Content Storage&quot;">​</a></h2><ol><li><strong>No JSON Encoding for Content</strong>: NEVER use <code>json_encode()</code> on HTML content strings before storing them in the <code>content</code> column.</li><li><strong>Raw HTML</strong>: Always store article content as raw, valid HTML.</li><li><strong>Translation Overrides</strong>: When an article is requested in a different language, the system checks the <code>translations</code> JSON column. If the translation exists, it overrides the default language fields.</li></ol>',11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};